import {
  AuthUnavailable,
  EmailAddress,
  Forbidden,
  LastAdmin,
  LastLead,
  MinimumGroupSize,
  NewPulseQuestion,
  OrderMismatch,
  OrganizationId,
  OrganizationSettings,
  PersonId,
  PersonNotFound,
  PersonWasRemoved,
  PulseDetail,
  PulseFull,
  PulseId,
  PulseList,
  PulseNeedsAQuestion,
  PulseNotFound,
  PulseSettings,
  QuestionAlreadyInPulse,
  QuestionContent,
  QuestionHasAnswers,
  QuestionId,
  QuestionNotFound,
  InvalidRoundState,
  InvitationNotFound,
  RoundDetail,
  RoundId,
  RoundList,
  RoundNotFound,
  RoundNotOpen,
  RoundResult,
  WeekOutOfRange,
  ActionId,
  ActionItem,
  ActionList,
  ActionNotFound,
  CreateAction,
  OwnerNotInTeam,
  UpdateAction,
  SessionState,
  TeamDetail,
  TeamId,
  TeamName,
  TeamNameTaken,
  TeamNotFound,
  TeamSummary,
  TimeZone,
  Unauthenticated,
} from "@surveybeat/domain";
import { Schema } from "effect";
import { HttpApi, HttpApiEndpoint, HttpApiGroup, HttpApiSchema } from "effect/http-api";

/** The name a creator gives a new Organization: trimmed, 1 to 100 characters. */
export const OrganizationName = Schema.String.pipe(
  Schema.check(Schema.isTrimmed(), Schema.isMinLength(1), Schema.isMaxLength(100)),
);

/**
 * Sign-in (WorkOS AuthKit, SPEC §6.1). `login`, `callback`, and `logout` answer with redirects
 * and cookies, so browsers navigate to them; the app calls the other three.
 */
export class AuthApiGroup extends HttpApiGroup.make("auth")
  .add(
    HttpApiEndpoint.get("login", "/login", { success: HttpApiSchema.Empty(302) }),
    HttpApiEndpoint.get("callback", "/callback", {
      query: { code: Schema.optional(Schema.String), state: Schema.optional(Schema.String) },
      success: HttpApiSchema.Empty(302),
    }),
    HttpApiEndpoint.post("logout", "/logout", {
      success: HttpApiSchema.Empty(303),
      error: [Forbidden, AuthUnavailable],
    }),
    HttpApiEndpoint.get("session", "/session", {
      success: SessionState,
      error: [Unauthenticated, AuthUnavailable],
    }),
    HttpApiEndpoint.post("createOrganization", "/organization", {
      payload: Schema.Struct({ name: OrganizationName }),
      success: SessionState,
      error: [Unauthenticated, Forbidden, AuthUnavailable],
    }),
    HttpApiEndpoint.post("chooseOrganization", "/organization/choose", {
      payload: Schema.Struct({ organizationId: OrganizationId }),
      success: SessionState,
      error: [Unauthenticated, Forbidden, AuthUnavailable],
    }),
  )
  .prefix("/auth") {}

/**
 * Every directory call needs a session in an Organization (`Forbidden` also covers "not in one"),
 * and any of them may meet a rule. `AuthUnavailable`: WorkOS could not be reached; repeat the call.
 */
const directoryErrors = [
  Unauthenticated,
  Forbidden,
  AuthUnavailable,
  TeamNotFound,
  PersonNotFound,
  PulseDetail,
  PulseFull,
  PulseId,
  PulseList,
  PulseNeedsAQuestion,
  PulseNotFound,
  PulseSettings,
  QuestionAlreadyInPulse,
  QuestionContent,
  QuestionHasAnswers,
  QuestionId,
  QuestionNotFound,
  LastLead,
  LastAdmin,
  TeamNameTaken,
  PersonWasRemoved,
] as const;
const teamParams = { teamId: TeamId };
const memberParams = { teamId: TeamId, personId: PersonId };

/**
 * Teams, Leads, members, and Organization settings, for the signed-in Person's Organization
 * (never one named in the URL). The permission table in `@surveybeat/domain` decides each call
 * from the Organization's Durable Object. No endpoint returns Result data. Changes answer 204 and
 * the app reads the view again, since a change can end the caller's own access to it.
 */
export class DirectoryApiGroup extends HttpApiGroup.make("directory")
  .add(
    HttpApiEndpoint.get("listTeams", "/teams", {
      success: Schema.Array(TeamSummary),
      error: directoryErrors,
    }),
    HttpApiEndpoint.post("createTeam", "/teams", {
      payload: Schema.Struct({ name: TeamName, timeZone: TimeZone, leadEmail: EmailAddress }),
      success: TeamDetail,
      error: directoryErrors,
    }),
    HttpApiEndpoint.get("getTeam", "/teams/:teamId", {
      params: teamParams,
      success: TeamDetail,
      error: directoryErrors,
    }),
    HttpApiEndpoint.patch("updateTeam", "/teams/:teamId", {
      params: teamParams,
      payload: Schema.Struct({ name: TeamName, timeZone: TimeZone }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.post("addMember", "/teams/:teamId/members", {
      params: teamParams,
      payload: Schema.Struct({ email: EmailAddress }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("removeMember", "/teams/:teamId/members/:personId", {
      params: memberParams,
      error: directoryErrors,
    }),
    HttpApiEndpoint.post("assignLead", "/teams/:teamId/leads", {
      params: teamParams,
      payload: Schema.Struct({ email: EmailAddress }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("removeLead", "/teams/:teamId/leads/:personId", {
      params: memberParams,
      error: directoryErrors,
    }),
    HttpApiEndpoint.get("getSettings", "/organization", {
      success: OrganizationSettings,
      error: directoryErrors,
    }),
    HttpApiEndpoint.patch("updateSettings", "/organization", {
      payload: Schema.Struct({ minimumGroupSize: MinimumGroupSize }),
      error: directoryErrors,
    }),
    HttpApiEndpoint.put("grantAdmin", "/organization/admins/:personId", {
      params: { personId: PersonId },
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("revokeAdmin", "/organization/admins/:personId", {
      params: { personId: PersonId },
      error: directoryErrors,
    }),
    HttpApiEndpoint.delete("removePerson", "/organization/people/:personId", {
      params: { personId: PersonId },
      error: directoryErrors,
    }),
  )
  .prefix("/api") {}

const pulseErrors = [
  Unauthenticated,
  Forbidden,
  AuthUnavailable,
  TeamNotFound,
  PulseNotFound,
  QuestionNotFound,
  QuestionAlreadyInPulse,
  QuestionHasAnswers,
  PulseNeedsAQuestion,
  PulseFull,
  OrderMismatch,
] as const;
const pulseParams = { teamId: TeamId, pulseId: PulseId };
const questionParams = { teamId: TeamId, pulseId: PulseId, questionId: QuestionId };

/**
 * The Pulse editor: a Team's Pulses, their settings, and their Questions, for the Team's Leads and
 * Organization admins (the permission table decides). Every change answers with the Pulse as the
 * editor shows it, with its estimated answer time and warnings. No endpoint returns Result data.
 */
export class PulsesApiGroup extends HttpApiGroup.make("pulses")
  .add(
    HttpApiEndpoint.get("listPulses", "/teams/:teamId/pulses", {
      params: teamParams,
      success: PulseList,
      error: pulseErrors,
    }),
    HttpApiEndpoint.post("createPulse", "/teams/:teamId/pulses", {
      params: teamParams,
      success: PulseDetail,
      error: pulseErrors,
    }),
    HttpApiEndpoint.get("getPulse", "/teams/:teamId/pulses/:pulseId", {
      params: pulseParams,
      success: PulseDetail,
      error: pulseErrors,
    }),
    HttpApiEndpoint.put("updatePulseSettings", "/teams/:teamId/pulses/:pulseId/settings", {
      params: pulseParams,
      payload: PulseSettings,
      success: PulseDetail,
      error: pulseErrors,
    }),
    HttpApiEndpoint.post("addQuestion", "/teams/:teamId/pulses/:pulseId/questions", {
      params: pulseParams,
      payload: NewPulseQuestion,
      success: PulseDetail,
      error: pulseErrors,
    }),
    HttpApiEndpoint.put("editQuestion", "/teams/:teamId/pulses/:pulseId/questions/:questionId", {
      params: questionParams,
      payload: QuestionContent,
      success: PulseDetail,
      error: pulseErrors,
    }),
    HttpApiEndpoint.delete("removeQuestion", "/teams/:teamId/pulses/:pulseId/questions/:questionId", {
      params: questionParams,
      success: PulseDetail,
      error: pulseErrors,
    }),
    HttpApiEndpoint.put("reorderQuestions", "/teams/:teamId/pulses/:pulseId/order", {
      params: pulseParams,
      payload: Schema.Struct({ order: Schema.Array(QuestionId) }),
      success: PulseDetail,
      error: pulseErrors,
    }),
  )
  .prefix("/api") {}

const roundErrors = [
  Unauthenticated,
  Forbidden,
  AuthUnavailable,
  TeamNotFound,
  PulseNotFound,
  RoundNotFound,
  RoundNotOpen,
  InvalidRoundState,
  WeekOutOfRange,
  InvitationNotFound,
] as const;

/**
 * Rounds and lifecycle controls: listing Rounds for a Pulse, viewing a Round, skipping weeks,
 * pausing and resuming Pulses, closing early, and cancelling. Authorized through the permission table.
 * No endpoint returns Result data.
 */
export class RoundsApiGroup extends HttpApiGroup.make("rounds")
  .add(
    HttpApiEndpoint.get("listRounds", "/teams/:teamId/pulses/:pulseId/rounds", {
      params: { teamId: TeamId, pulseId: PulseId },
      success: RoundList,
      error: roundErrors,
    }),
    HttpApiEndpoint.get("getRound", "/teams/:teamId/rounds/:roundId", {
      params: { teamId: TeamId, roundId: RoundId },
      success: RoundDetail,
      error: roundErrors,
    }),
    HttpApiEndpoint.post("skipWeek", "/teams/:teamId/pulses/:pulseId/skip", {
      params: { teamId: TeamId, pulseId: PulseId },
      payload: Schema.Struct({ plannedOpenDate: Schema.String }),
      success: Schema.Void,
      error: roundErrors,
    }),
    HttpApiEndpoint.post("unskipWeek", "/teams/:teamId/pulses/:pulseId/unskip", {
      params: { teamId: TeamId, pulseId: PulseId },
      payload: Schema.Struct({ plannedOpenDate: Schema.String }),
      success: Schema.Void,
      error: roundErrors,
    }),
    HttpApiEndpoint.post("pausePulse", "/teams/:teamId/pulses/:pulseId/pause", {
      params: { teamId: TeamId, pulseId: PulseId },
      success: Schema.Void,
      error: roundErrors,
    }),
    HttpApiEndpoint.post("resumePulse", "/teams/:teamId/pulses/:pulseId/resume", {
      params: { teamId: TeamId, pulseId: PulseId },
      success: Schema.Void,
      error: roundErrors,
    }),
    HttpApiEndpoint.post("closeRoundEarly", "/teams/:teamId/rounds/:roundId/close", {
      params: { teamId: TeamId, roundId: RoundId },
      success: RoundDetail,
      error: roundErrors,
    }),
    HttpApiEndpoint.post("cancelRound", "/teams/:teamId/rounds/:roundId/cancel", {
      params: { teamId: TeamId, roundId: RoundId },
      success: RoundDetail,
      error: roundErrors,
    }),
    HttpApiEndpoint.post("resendInvitation", "/teams/:teamId/rounds/:roundId/invitations/:personId/resend", {
      params: { teamId: TeamId, roundId: RoundId, personId: PersonId },
      success: Schema.Void,
      error: roundErrors,
    }),
    HttpApiEndpoint.get("getResults", "/teams/:teamId/rounds/:roundId/results", {
      params: { teamId: TeamId, roundId: RoundId },
      success: RoundResult,
      error: roundErrors,
    }),
  )
  .prefix("/api") {}

const actionErrors = [
  Unauthenticated,
  Forbidden,
  AuthUnavailable,
  TeamNotFound,
  RoundNotFound,
  ActionNotFound,
  OwnerNotInTeam,
  PersonNotFound,
] as const;

/**
 * Team Actions: commitments made from Results (slice 13).
 * Lead creates and updates actions; team members can view.
 * The Actions list has no minimum group size.
 */
export class ActionsApiGroup extends HttpApiGroup.make("actions")
  .add(
    HttpApiEndpoint.get("listActions", "/teams/:teamId/actions", {
      params: { teamId: TeamId },
      success: ActionList,
      error: actionErrors,
    }),
    HttpApiEndpoint.post("createAction", "/teams/:teamId/actions", {
      params: { teamId: TeamId },
      payload: CreateAction,
      success: ActionItem,
      error: actionErrors,
    }),
    HttpApiEndpoint.patch("updateAction", "/teams/:teamId/actions/:actionId", {
      params: { teamId: TeamId, actionId: ActionId },
      payload: UpdateAction,
      success: ActionItem,
      error: actionErrors,
    }),
  )
  .prefix("/api") {}

/** The HttpApi declaration shared by the server and the clients. */
export class SurveyBeatApi extends HttpApi.make("surveybeat")
  .add(AuthApiGroup)
  .add(DirectoryApiGroup)
  .add(PulsesApiGroup)
  .add(RoundsApiGroup)
  .add(ActionsApiGroup) {}
import { PulseId, RoundId, TeamId } from "@surveybeat/domain";
import { pipe, Schema } from "effect";
import {
  defineRouteUnion,
  literal,
  mapTo,
  oneOf,
  parseUrlWithFallback,
  root,
  schemaSegment,
  slash,
} from "foldkit/route";
import type { Url } from "foldkit/url";

export const AppRoute = defineRouteUnion({
  Teams: {},
  Team: { teamId: TeamId },
  Pulses: { teamId: TeamId },
  Pulse: { teamId: TeamId, pulseId: PulseId },
  RoundResults: { teamId: TeamId, roundId: RoundId },
  Settings: {},
  Privacy: {},
  NotFound: { path: Schema.String },
});
export type AppRoute = typeof AppRoute.Type;

export const teamsRouter = pipe(root, mapTo(AppRoute.Teams));
export const settingsRouter = pipe(literal("settings"), mapTo(AppRoute.Settings));
export const privacyRouter = pipe(literal("privacy"), mapTo(AppRoute.Privacy));
export const teamRouter = pipe(
  literal("teams"),
  slash(schemaSegment("teamId", TeamId)),
  mapTo(AppRoute.Team),
);
export const pulsesRouter = pipe(
  literal("teams"),
  slash(schemaSegment("teamId", TeamId)),
  slash(literal("pulses")),
  mapTo(AppRoute.Pulses),
);
export const pulseRouter = pipe(
  literal("teams"),
  slash(schemaSegment("teamId", TeamId)),
  slash(literal("pulses")),
  slash(schemaSegment("pulseId", PulseId)),
  mapTo(AppRoute.Pulse),
);
export const roundResultsRouter = pipe(
  literal("teams"),
  slash(schemaSegment("teamId", TeamId)),
  slash(literal("rounds")),
  slash(schemaSegment("roundId", RoundId)),
  mapTo(AppRoute.RoundResults),
);

export const appRouter = oneOf(
  roundResultsRouter,
  pulseRouter,
  pulsesRouter,
  teamRouter,
  settingsRouter,
  privacyRouter,
  teamsRouter,
);
export const urlToAppRoute = (url: Url): AppRoute => parseUrlWithFallback(appRouter, AppRoute.NotFound)(url);

export const teamsHref = () => teamsRouter.build({});
export const settingsHref = () => settingsRouter.build({});
export const privacyHref = () => privacyRouter.build({});
export const teamHref = (teamId: TeamId) => teamRouter.build({ teamId });
export const pulsesHref = (teamId: TeamId) => pulsesRouter.build({ teamId });
export const pulseHref = (teamId: TeamId, pulseId: PulseId) => pulseRouter.build({ teamId, pulseId });
export const roundResultsHref = (teamId: TeamId, roundId: RoundId) =>
  roundResultsRouter.build({ teamId, roundId });
import { SurveyBeatApi } from "@surveybeat/api";
import { Effect, Predicate, Schema } from "effect";
import { FetchHttpClient } from "effect/http";
import { HttpApiClient } from "effect/http-api";
import { message } from "../messages/index.ts";

export const Failure = Schema.Literals([
  "Unauthenticated",
  "Forbidden",
  "NotFound",
  "LastLead",
  "LastAdmin",
  "TeamNameTaken",
  "QuestionAlreadyInPulse",
  "QuestionHasAnswers",
  "PulseNeedsAQuestion",
  "PulseFull",
  "OrderMismatch",
  "Invalid",
  "Unavailable",
]);
export type Failure = typeof Failure.Type;

export const failureMessage = (failure: Failure): string => {
  switch (failure) {
    case "Unauthenticated":
      return message("error.Unauthenticated");
    case "Forbidden":
      return message("error.Forbidden");
    case "NotFound":
      return message("error.NotFound");
    case "LastLead":
      return message("error.LastLead");
    case "LastAdmin":
      return message("error.LastAdmin");
    case "TeamNameTaken":
      return message("error.TeamNameTaken");
    case "QuestionAlreadyInPulse":
      return message("error.QuestionAlreadyInPulse");
    case "QuestionHasAnswers":
      return message("error.QuestionHasAnswers");
    case "PulseNeedsAQuestion":
      return message("error.PulseNeedsAQuestion");
    case "PulseFull":
      return message("error.PulseFull");
    case "OrderMismatch":
      return message("error.OrderMismatch");
    case "Invalid":
      return message("error.Invalid");
    case "Unavailable":
      return message("error.Unavailable");
  }
};

export const failureOf = (error: unknown): Failure => {
  if (Predicate.isTagged(error, "Unauthenticated")) return "Unauthenticated";
  if (Predicate.isTagged(error, "Forbidden")) return "Forbidden";
  if (
    Predicate.isTagged(error, "TeamNotFound") ||
    Predicate.isTagged(error, "PersonNotFound") ||
    Predicate.isTagged(error, "PulseNotFound") ||
    Predicate.isTagged(error, "QuestionNotFound") ||
    Predicate.isTagged(error, "RoundNotFound") ||
    Predicate.isTagged(error, "ActionNotFound") ||
    Predicate.isTagged(error, "ResultsNotReady")
  )
    return "NotFound";
  if (Predicate.isTagged(error, "OwnerNotInTeam")) return "Invalid";
  if (Predicate.isTagged(error, "LastLead")) return "LastLead";
  if (Predicate.isTagged(error, "LastAdmin")) return "LastAdmin";
  if (Predicate.isTagged(error, "TeamNameTaken")) return "TeamNameTaken";
  for (const tag of [
    "QuestionAlreadyInPulse",
    "QuestionHasAnswers",
    "PulseNeedsAQuestion",
    "PulseFull",
    "OrderMismatch",
  ] as const) {
    if (Predicate.isTagged(error, tag)) return tag;
  }
  if (Predicate.isTagged(error, "HttpApiSchemaError") || Predicate.isTagged(error, "SchemaError"))
    return "Invalid";
  return "Unavailable";
};

export const clientEffect = HttpApiClient.make(SurveyBeatApi, {
  baseUrl: typeof window !== "undefined" ? window.location.origin : "http://localhost",
});
export type ApiClient = Effect.Success<typeof clientEffect>;

export const runApi = <A, M>(
  f: (api: ApiClient) => Effect.Effect<A, unknown>,
  onSuccess: (value: A) => M,
  onFailure: (failure: Failure) => M,
): Effect.Effect<M> =>
  clientEffect.pipe(
    Effect.flatMap(f),
    Effect.map(onSuccess),
    Effect.catch((error: unknown) => Effect.succeed(onFailure(failureOf(error)))),
    Effect.provide(FetchHttpClient.layer),
  );
